// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(amount > 0 && amount <= address(this).balance + 1e30);
        // fund the contract via its payable receive() from the owner (this contract)
        vm.deal(address(this), amount);
        (bool okSend, ) = address(c).call{value: amount}("");
        assertTrue(okSend);
        uint256 preBalance = address(c).balance;
        uint256 ownerBefore = address(this).balance;
        // owner (deployer == this contract) withdraws everything
        c.withdrawAll();
        uint256 ownerAfter = address(this).balance;
        // Rule: withdrawAll transfers the ENTIRE pre-call contract balance to the recipient
        assertTrue(ownerAfter - ownerBefore == preBalance);
    }

    receive() external payable {}
}
